package org.apache.commons.lang3.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DateUtils_isSameDay_TriageGen1Test {

    @Test
    public void testIsSameDay_SameDaySameTime() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30);
        assertTrue(DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_SameDayDifferentTime() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 10, 30);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 23, 59);
        assertTrue(DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentDay() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 2);
        assertFalse(DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentMonth() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Calendar cal2 = new GregorianCalendar(2023, Calendar.FEBRUARY, 1);
        assertFalse(DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentYear() {
        Calendar cal1 = new GregorianCalendar(2023, Calendar.JANUARY, 1);
        Calendar cal2 = new GregorianCalendar(2024, Calendar.JANUARY, 1);
        assertFalse(DateUtils.isSameDay(cal1, cal2));
    }

    @Test
    public void testIsSameDay_DifferentEra() {
        // Testing the ERA branch (e.g., BC vs AD)
        // Note: Setting ERA manually is tricky with GregorianCalendar, 
        // but we can simulate by using a very old date if the system allows or assuming the logic covers it.
        Calendar cal1 = new GregorianCalendar(1, Calendar.JANUARY, 1); // Year 1 AD
        Calendar cal2 = new GregorianCalendar(-1, Calendar.JANUARY, 1); // Year 1 BC (approx)

        // Since we can't easily force ERA without deep reflection or specific implementations, 
        // we ensure that if eras differ, it returns false.
        // For standard testing, we verify the logic:
        assertFalse(DateUtils.isSameDay(cal1, cal2));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameDay_FirstParamNull() {
        DateUtils.isSameDay(null, new GregorianCalendar());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameDay_SecondParamNull() {
        DateUtils.isSameDay(new GregorianCalendar(), null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIsSameDay_BothParamsNull() {
        DateUtils.isSameDay(null, null);
    }
}
